const productDigitalRows = `-- name: ProductDigitalRows :many
SELECT p.digital,
       df.id AS file_id, df.name AS file_name, df.ext AS file_ext,
       dd.id AS data_id, dd.content AS data_content, dd.cart_id AS data_cart_id
FROM product p
LEFT JOIN digital_file df ON p.id = df.product_id
LEFT JOIN digital_data dd ON p.id = dd.product_id
WHERE p.id = ?1
`

type ProductDigitalRowsRow struct {
	Digital     sql.NullString
	FileID      sql.NullString
	FileName    sql.NullString
	FileExt     sql.NullString
	DataID      sql.NullString
	DataContent sql.NullString
	DataCartID  sql.NullString
}

func (q *Queries) ProductDigitalRows(ctx context.Context, productID string) ([]ProductDigitalRowsRow, error) {
	rows, err := q.db.QueryContext(ctx, productDigitalRows, productID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ProductDigitalRowsRow
	for rows.Next() {
		var i ProductDigitalRowsRow
		if err := rows.Scan(
			&i.Digital,
			&i.FileID,
			&i.FileName,
			&i.FileExt,
			&i.DataID,
			&i.DataContent,
			&i.DataCartID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

